using Avalonia.Controls;using Avalonia.Layout;namespace WhatSchedule.Controls;public sealed class TextPromptDialog : Window{	private TextPromptDialog(string title, string caption, string defaultText)	{		Title = title;		WindowStartupLocation = WindowStartupLocation.CenterOwner;		SizeToContent = SizeToContent.WidthAndHeight;		CanResize = false;		ShowInTaskbar = false;		MinWidth = 360;		var textBox = new TextBox		{			Text = defaultText,			Watermark = caption,			Width = 320,		};		var okButton = new Button { Content = "OK", IsDefault = true };		var cancelButton = new Button { Content = "Cancel", IsCancel = true };		okButton.Click += (_, _) => Close(textBox.Text);		cancelButton.Click += (_, _) => Close(null);		Content = new StackPanel		{			Margin = new Avalonia.Thickness(12),			Spacing = 12,			Children =			{				textBox,				new StackPanel				{					Orientation = Orientation.Horizontal,					Spacing = 8,					HorizontalAlignment = HorizontalAlignment.Right,					Children = { okButton, cancelButton },				},			},		};		Opened += (_, _) => textBox.Focus();	}	/// <summary>	/// Shows the dialog and returns the entered text,	/// or null if it was cancelled or closed without accepting.	/// </summary>	public static async Task<string?> Show(Window owner, string title, string caption, string defaultText = "")	{		var dialog = new TextPromptDialog(title, caption, defaultText);		return await dialog.ShowDialog<string?>(owner);	}}